import json,subprocess,sys
MAIN='submission/main.py'
def run(doc):
    p=subprocess.run([sys.executable,'-I','-B',MAIN],input=json.dumps(doc).encode(),capture_output=True)
    return p.returncode,json.loads(p.stdout) if p.returncode==0 else None
def msg(start,headers,body=b''):
    return (('\r\n'.join([start]+headers)+'\r\n\r\n').encode()+body).hex()
cfg={"accounts":[{"id":"alice","default":"sip:alice@lab.test","aliases":["sip:alice@lab.test","tel:+12025550100"]}],"peers":[{"id":"e","mode":"access","accounts":[]},{"id":"r","mode":"relay","accounts":["alice"]}],"ttl_ms":10000,"capacity":100}
def build(priv,egress,relay=False,callid='c'):
    hs=['From: sip:alice@lab.test;tag=t','To: <sip:bob@lab.test>',f'Call-ID: {callid}','CSeq: 1 MESSAGE']
    if relay: hs.append('P-Asserted-Identity: <sip:alice@lab.test>, <tel:+12025550100>')
    else: hs.append('P-Preferred-Identity: <sip:alice@lab.test>, <tel:+12025550100>')
    if priv!='absent': hs.append('Privacy: '+priv)
    hs.append('Content-Length: 0')
    return msg('MESSAGE sip:bob@lab.test SIP/2.0',hs)
evs=[];t=0
for relay in (False,True):
    for priv in ('absent','id','none'):
        for eg in ('internal','external'):
            t+=1
            evs.append({"t":t,"peer":'r' if relay else 'e',"auth":None if relay else "alice","egress":eg,"wire_hex":build(priv,eg,relay,callid=f'{relay}-{priv}-{eg}')})
rc,j=run({"version":1,"config":cfg,"events":evs})
print('rc',rc)
for r in j['results']:
